func (server *Server) rehash() error {
	config := server.Config()
	newConfig, err := LoadConfig(config.Datastore.Path)
	if err != nil { return err }
	if err := server.applyConfig(newConfig); err != nil { return err }
	server.logger.Info("server", "rehashing complete")
	return nil
}
